#include <bits/stdc++.h>
using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) {
        res *= i;
    }
    return res;
}

long long A(int n, int k) {
    return factorial(n) / factorial(n - k);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    string line;
    getline(cin, line);
    stringstream ss(line);
    ss >> n >> mod;
    if (n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> z_array(1, 1);
    long long total_sum = 0;
    for (int i = 2; i <= n; ++i) {
        int size_next_z = (i * i) / 2;
        vector<long long> next_z_array(size_next_z, 0);
        for (size_t j = 0; j < z_array.size(); ++j) {
            for (int k = 0; k < i; ++k) {
                if (z_array[j] > 0) {
                    int index = i - k - 1 + j;
                    if (index >= 0 && index < size_next_z) {
                        next_z_array[index] += z_array[j];
                    }
                }
            }
        }
        vector<long long> prefix_array(z_array.size() + 1, 0);
        for (int w = (int)z_array.size() - 1; w >= 0; --w) {
            prefix_array[w] = (prefix_array[w + 1] + z_array[w]) % mod;
        }
        vector<long long> e_vals(prefix_array.size(), 0);
        vector<long long> f_vals(prefix_array.size(), 0);
        for (size_t w = 0; w + 1 < prefix_array.size(); ++w) {
            e_vals[w + 1] = (e_vals[w] + prefix_array[w]) % mod;
            f_vals[w + 1] = (f_vals[w] - (long long)w * prefix_array[w]) % mod;
        }
        long long temp_sum = 0;
        for (size_t jj = 0; jj < z_array.size(); ++jj) {
            int L = (int)jj + 2;
            int R = min((int)z_array.size() - 1, i + (int)jj);
            long long ccc = 0;
            if (R >= L) {
                ccc = ((e_vals[R + 1] - e_vals[L]) % mod + mod) % mod;
                ccc = (ccc * (i + 1 + (int)jj)) % mod;
                ccc = (ccc + ((f_vals[R + 1] - f_vals[L]) % mod + mod) % mod) % mod;
            }
            total_sum = (total_sum + ccc * z_array[jj]) % mod;
        }
        total_sum = (total_sum + total_sum * A(n, n - i)) % mod;
        z_array = next_z_array;
    }
    cout << total_sum % mod << "\n";
    return 0;
}
